(() => {
  const root = document.getElementById('app');
  const esc = v => String(v ?? '').replace(/[&<>\"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[m]));
  const key='cloudblitz-linkedin-genai-checks-v1';
  const defaultChecks=['Professional photo','GenAI Engineer headline','Custom LinkedIn URL','About section completed','Experience with measurable impact','GenAI technical skills','LLM APIs / Azure / GCP skills','RAG & Vector Search skills','Embeddings / IaC skills','Prompt Engineering / Agents skills','Monitoring & observability skills','Projects with architecture and outcomes','GitHub links added','Certifications added','Education completed','Featured section configured','Open to Work configured','Location and contact details','Recruiter keywords aligned with resume','Resume / LinkedIn / Naukri information consistent'];
  const saved=()=>{try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}};
  const setSaved=a=>localStorage.setItem(key,JSON.stringify(a));
  window.linkedin100=()=>{const done=saved(),pct=Math.round(done.length/defaultChecks.length*100);return `<div class="li100"><div class="li-hero"><div><span class="li-eyebrow">CLOUDBLITZ · LINKEDIN PROFILE LAB</span><h2>100% LinkedIn Profile — GenAI Engineer</h2><p>Student-ready LinkedIn profile structure for GenAI Engineer roles. Complete every section, align the profile with the resume, and keep all claims truthful and interview-ready.</p></div><div class="li-score"><b>${pct}%</b><span>Profile Complete</span></div></div><div class="li-grid"><section class="li-card"><div class="li-card-head"><div><span class="li-label">PROFILE BLUEPRINT</span><h3>Recommended GenAI Profile</h3></div><button class="pill-btn" onclick="window.print()">Print Checklist</button></div><div class="li-preview"><div class="li-cover"><span>GENAI • CLOUD • AUTOMATION</span></div><div class="li-avatar">AW</div><div class="li-profile-main"><h2>GenAI Engineer</h2><p class="li-headline">GenAI Engineer | LLM APIs | RAG | Vector Search | Embeddings | Prompt Engineering | Agents | Python | Cloud & Automation</p><p class="li-location">Pune, Maharashtra, India · Open to GenAI / Cloud Engineer opportunities</p><div class="li-actions"><button>Connect</button><button>Message</button><button>More</button></div></div><div class="li-section"><h4>About</h4><p>GenAI Engineer focused on cloud infrastructure, Agents automation, containerization and reliable application delivery. Hands-on with LLM APIs, RAG, Vector Search, Embeddings, Prompt Engineering, Git and Python, with experience building automated deployment workflows and supporting scalable environments.</p><p>Experienced in Responsible AI, container orchestration, monitoring and troubleshooting. Comfortable collaborating with development teams to improve deployment consistency, release speed and operational reliability.</p><p>Currently focused on GenAI, Cloud and Platform Engineering opportunities where automation, scalability and continuous improvement are core priorities.</p></div><div class="li-section"><h4>Experience</h4><div class="li-role"><b>GenAI Engineer / GenAI Engineer Intern</b><span>Cloud & GenAI · Pune · Add actual dates</span><ul><li>Built and maintained Agents pipelines using Prompt Engineering and Git-based workflows.</li><li>Containerized applications with RAG and deployed workloads using Vector Search.</li><li>Automated LLM APIs infrastructure using Embeddings and managed repeatable environments.</li><li>Implemented monitoring and troubleshooting using Evaluation, LangChain and LangGraph.</li><li>Collaborated with developers to improve deployment reliability and release workflows.</li></ul></div></div><div class="li-section"><h4>Featured Projects</h4><div class="li-project"><b>End-to-End GenAI Agents Platform</b><span>LLM APIs · Prompt Engineering · RAG · Vector Search · Embeddings · FastAPI</span><p>Automated build, quality checks, containerization, deployment and infrastructure provisioning. Add the student's real GitHub repository and measurable project outcomes.</p></div><div class="li-project"><b>Cloud Infrastructure Automation</b><span>LLM APIs · Embeddings · Git · Python</span><p>Provisioned reusable cloud infrastructure with Responsible AI. Replace sample claims with the student's verified implementation.</p></div></div><div class="li-section"><h4>Skills</h4><div class="li-skills">${['GenAI','Amazon Web Services (LLM APIs)','RAG','Vector Search','Embeddings','Prompt Engineering','Git','Python','Agents','GitHub Actions','Evaluation','LangChain','LLM APIs LangGraph','FastAPI','Vector Databases','Python','LLMOps','Responsible AI'].map(x=>`<span>${x}</span>`).join('')}</div></div><div class="li-section"><h4>Education & Certifications</h4><p><b>Education:</b> Add actual degree, institution and year.</p><p><b>Certifications:</b> Add only certifications actually earned, with official names.</p></div></div></section><aside class="li-card li-check"><div class="li-card-head"><div><span class="li-label">100% CHECKLIST</span><h3>Profile Completion</h3></div><b>${done.length}/${defaultChecks.length}</b></div><div class="li-progress"><i style="width:${pct}%"></i></div>${defaultChecks.map((x,i)=>`<label class="li-check-row"><input type="checkbox" ${done.includes(i)?'checked':''} onchange="toggleLinkedIn(${i},this.checked)"><span>${esc(x)}</span><b>${done.includes(i)?'✓':''}</b></label>`).join('')}</aside></div><div class="li-bottom-grid"><div class="li-tip"><b>Recruiter Keyword Rule</b><p>Use the same truthful role keywords across LinkedIn, resume and Naukri: GenAI Engineer, LLM APIs, RAG, Vector Search, Embeddings, Prompt Engineering, Agents, Python, monitoring and Responsible AI.</p></div><div class="li-tip"><b>Consistency Rule</b><p>Job titles, dates, skills, project names, GitHub links and experience claims must match the student's actual resume and interview explanation.</p></div></div></div>`};
  window.toggleLinkedIn=(i,v)=>{let a=saved();if(v&&!a.includes(i))a.push(i);if(!v)a=a.filter(x=>x!==i);setSaved(a);linkedinRender()};
  window.linkedinRender=()=>{root.innerHTML=`<div class="app"><header class="topbar"><div class="brand"><div class="brandmark">CB</div><div><h1>CloudBlitz GenAI Placement Training</h1><small>LinkedIn Profile Lab · GenAI Engineer</small></div></div><div class="top-actions"><button class="pill-btn" onclick="show('home')">← Dashboard</button></div></header><main class="content">${linkedin100()}<footer class="footer">CloudBlitz · GenAI Placement & Training Program 2026 · LinkedIn Profile Lab</footer></main></div>`};
  const oldRender=window.render;
  window.showLinkedIn=()=>linkedinRender();
})();